SELECT country, COUNT(*) AS customers, MIN(first_order_date) AS first, MAX(last_order_date) AS last
FROM gold.customer_lifetime
WHERE country ILIKE 'turkey'
GROUP BY country;

SELECT country, COUNT(*) AS customers
FROM gold.customer_lifetime
WHERE first_order_date <= DATE '2026-09-30'
GROUP BY country
ORDER BY country;

SELECT MIN(first_order_date), MAX(last_order_date) FROM gold.customer_lifetime;

SELECT COUNT(*) AS customers
FROM gold.customer_lifetime
WHERE country = 'TR' AND first_order_date <= DATE '2026-09-30';

SELECT table_name, column_name, data_type FROM information_schema.columns 
WHERE table_name IN ('exposed.daily_sales_with_weather','exposed.net_sales_daily','gold.daily_sales','legacy.daily_net_sales','exposed.sales_by_country_daily')
ORDER BY table_name, ordinal_position;

SELECT table_name, column_name, data_type FROM information_schema.columns 
WHERE table_name LIKE '%sales%' OR table_name LIKE '%net_sales%'
ORDER BY table_name, ordinal_position;

SELECT SUM(net_revenue_eur) AS net_revenue_eur, COUNT(*) AS days
FROM exposed.net_sales_daily
WHERE order_date BETWEEN DATE '2026-10-01' AND DATE '2026-10-10';

SELECT SUM(net_revenue) AS net_revenue, COUNT(*) AS days
FROM legacy.daily_net_sales
WHERE sales_date BETWEEN DATE '2026-10-01' AND DATE '2026-10-10';

SELECT activity_date, engaged_customers_7d
FROM gold.customer_engagement_daily
WHERE activity_date = DATE '2026-10-03';

SELECT DISTINCT country
FROM exposed.sales_by_country_daily
ORDER BY country;

SELECT table_schema, table_name, column_name, data_type
FROM information_schema.columns
WHERE (table_schema, table_name) IN (
  ('gold','daily_sales'),('exposed','daily_sales_with_weather'),('exposed','net_sales_daily'),('legacy','daily_net_sales')
)
ORDER BY table_schema, table_name, ordinal_position;

SELECT sum(revenue_eur) AS total_revenue_eur, count(*) AS days_count
FROM gold.daily_sales
WHERE order_date BETWEEN DATE '2026-09-25' AND DATE '2026-10-01';

SELECT table_schema, table_name, column_name
FROM information_schema.columns
WHERE column_name ILIKE '%cancel%' OR column_name ILIKE '%return%';

SELECT SUM(revenue_eur) AS total_gmv
FROM gold.daily_sales
WHERE order_date >= DATE '2026-09-01' AND order_date <= DATE '2026-09-30';

SELECT MIN(activity_date), MAX(activity_date), COUNT(*) AS days
FROM gold.customer_engagement_daily;
SELECT activity_date, cart_sessions, checkout_sessions, cart_to_checkout_rate
FROM gold.customer_engagement_daily
WHERE activity_date BETWEEN DATE '2026-09-20' AND DATE '2026-10-03'
ORDER BY activity_date;

SELECT activity_date, cart_sessions, checkout_sessions, cart_to_checkout_rate
FROM gold.customer_engagement_daily
ORDER BY activity_date;

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'exposed' AND table_name = 'net_sales_daily';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'exposed' AND table_name = 'daily_sales_with_weather';

SELECT DISTINCT channel
FROM gold.customer_actions_daily
ORDER BY channel;

SELECT table_schema, table_name, column_name, data_type
FROM information_schema.columns
WHERE (table_schema, table_name) IN (
  ('gold','daily_sales'), ('exposed','net_sales_daily'), ('exposed','daily_sales_with_weather'), ('exposed','sales_by_country_daily'), ('legacy','daily_net_sales')
)
ORDER BY table_schema, table_name, ordinal_position;

SELECT SUM(revenue_eur) AS total_revenue_eur
FROM gold.daily_sales
WHERE order_date BETWEEN '2026-09-01' AND '2026-09-30';

SELECT SUM(net_revenue_eur) AS total_net_revenue_eur
FROM exposed.net_sales_daily
WHERE order_date BETWEEN '2026-09-01' AND '2026-09-30';

SELECT min(order_date), max(order_date), count(*)
FROM exposed.net_sales_daily;
SELECT order_date, revenue_eur, returns_eur, net_revenue_eur, (revenue_eur - returns_eur) AS calc
FROM exposed.net_sales_daily
WHERE order_date BETWEEN DATE '2026-10-05' AND DATE '2026-10-11'
ORDER BY order_date;
SELECT SUM(revenue_eur) AS gross_noncancelled, SUM(returns_eur) AS returns_credited, SUM(net_revenue_eur) AS net_revenue_week
FROM exposed.net_sales_daily
WHERE order_date BETWEEN DATE '2026-10-05' AND DATE '2026-10-11';

SELECT SUM(revenue_eur) AS orders_placed, SUM(returns_eur) AS returns_credited, SUM(revenue_eur) - SUM(returns_eur) AS net_revenue_eur
FROM exposed.net_sales_daily
WHERE order_date BETWEEN DATE '2026-10-05' AND DATE '2026-10-10';

SELECT table_schema, table_name FROM information_schema.tables
WHERE table_schema IN ('exposed','gold','legacy')
ORDER BY table_schema, table_name;

SELECT DISTINCT channel
FROM exposed.channel_performance_daily
ORDER BY channel;
SELECT MIN(activity_date), MAX(activity_date)
FROM exposed.channel_performance_daily;

SELECT table_schema, table_name, column_name, data_type
FROM information_schema.columns
WHERE (table_schema, table_name) IN (
  ('exposed','outreach_activation'),('gold','customer_actions_daily'),('gold','customer_engagement_daily')
)
ORDER BY table_schema, table_name, ordinal_position;

SELECT table_schema, table_name, column_name, data_type
FROM information_schema.columns
ORDER BY table_schema, table_name, ordinal_position;

SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY lifetime_value_eur) AS median_eur
FROM (
  SELECT lifetime_value_eur FROM gold.customer_lifetime
  ORDER BY first_order_date ASC, customer_id ASC
  LIMIT 10
) s;

SELECT COUNT(*) AS customer_count
FROM silver.customers
WHERE country = 'Turkey' AND signup_date <= DATE '2026-09-30';

SELECT COUNT(*) AS customer_count
FROM silver.customers
WHERE country = 'TR' AND signup_date <= DATE '2026-09-30';

SELECT 
  min(spend_date) AS min_spend, max(spend_date) AS max_spend, count(*) AS spend_rows
FROM silver.ad_spend;

SELECT 
  min(snapshot_date) AS min_snap, max(snapshot_date) AS max_snap, count(*) AS snap_rows
FROM silver.campaign_budgets;

SELECT 
  sum(budget_eur) AS total_budget
FROM (
  SELECT DISTINCT campaign_id, budget_eur
  FROM silver.campaign_budgets
) b;

SELECT column_name, data_type FROM information_schema.columns
WHERE table_schema='gold' AND table_name='customer_engagement_daily'
ORDER BY ordinal_position;

SELECT column_name, data_type FROM information_schema.columns
WHERE table_schema='gold' AND table_name='daily_sales'
ORDER BY ordinal_position;

SELECT stage, COUNT(*) FROM silver.candidate_stages GROUP BY stage ORDER BY stage;
SELECT current_stage, COUNT(*) FROM silver.applications GROUP BY current_stage ORDER BY current_stage;
SELECT MIN(applied_date), MAX(applied_date) FROM silver.applications;

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_name = 'call_signals_daily' AND table_schema = 'gold';

SELECT status, count(*), sum(amount)
FROM silver.orders
GROUP BY status;

SELECT campaign_id, name, channel, market, start_date
FROM silver.campaigns
WHERE channel ILIKE '%email%'
ORDER BY campaign_id;

SELECT MIN(spend_date), MAX(spend_date) FROM silver.ad_spend;

SELECT channel, COUNT(*) FROM silver.campaigns GROUP BY channel ORDER BY channel;

SELECT campaign_id, name, channel, market, start_date
FROM silver.campaigns
WHERE channel ILIKE '%search%' OR name ILIKE '%search%';

SELECT DISTINCT country
FROM exposed.sales_by_country_daily
ORDER BY country;
